import logging
import os
import sys


def _no_shutdown():
    pass


shutdown_call = _no_shutdown
need_restart = False

_startup_cwd = os.getcwd()


def restart():
    # based on:
    # https://stackoverflow.com/questions/1750757/restarting-a-self-updating-python-script
    # https://github.com/cherrypy/cherrypy/blob/0857fa81eb0ab647c7b59a019338bab057f7748b/cherrypy/process/wspbus.py#L305
    # https://github.com/cherrypy/cherrypy/blob/main/cherrypy/process/wspbus.py#L379
    args = sys.argv[:]
    args.insert(0, sys.executable)
    logging.warning('Re-spawning %s' % ' '.join(args))
    os.chdir(_startup_cwd)
    os.execv(sys.executable, args)


def should_restart():
    return need_restart


def shutdown_app(restart_after_shutdown=False):
    """
    Trigger graceful shutdown of application

    :param restart_after_shutdown: register need to signal "restart request"
    """
    global need_restart
    if shutdown_call != _no_shutdown:
        need_restart = restart_after_shutdown
        shutdown_call()


async def shutdown_when_done(main_awaitable):
    try:
        await main_awaitable
    finally:
        # if our main functionality finishes we want to close our runner
        # to not end up with asyncio loop doing nothing (just awaiting for Ctrl-C)
        shutdown_app(restart_after_shutdown=should_restart())


def register(shutdown):
    """Register callable that triggers graceful shutdown of application"""
    global shutdown_call
    shutdown_call = shutdown
